import{_ as n,C as r,o as e,c as o,a2 as s,b as l,w as i,a as d,E as h,a3 as c}from"./chunks/framework.Bqn-bhhR.js";const E=JSON.parse('{"title":"Dynamic Tree-sitter Grammars","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dynamic-grammars.md","filePath":"guide/dynamic-grammars.md","lastUpdated":1793230489000}'),p={name:"guide/dynamic-grammars.md"};function g(m,a,k,u,y,f){const t=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=s(`<h1 id="dynamic-tree-sitter-grammars" tabindex="-1">Dynamic Tree-sitter Grammars <a class="header-anchor" href="#dynamic-tree-sitter-grammars" aria-label="Permalink to &quot;Dynamic Tree-sitter Grammars&quot;">​</a></h1><p>Codemark supports 8 languages built in (Rust, Swift, TypeScript/TSX, Python, Go, Java, Dart, C#), and <strong>any other language</strong> via dynamic WASM grammar loading — no recompilation needed. This page covers how it works in <code>crates/codemark-core/src/grammar/</code> and <code>parser/registry.rs</code>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Built-in languages are statically compiled into the binary. Dynamic languages are WASM grammars loaded at runtime from a cache directory. A single process-global <a href="https://wasmtime.dev/" target="_blank" rel="noreferrer">wasmtime</a> <code>Engine</code> backs all WASM stores.</p><p><strong>A dynamic grammar wins resolution over a built-in of the same name or extension.</strong> An installed grammar is something you went out of your way to add, so it reads as the more specific intent — and it makes a built-in <em>replaceable</em>, which is what allows a bundled language to be dropped from the binary and picked up from the registry without its extension becoming unresolvable.</p><p>Shadowing is never accidental: installing a grammar that claims a built-in&#39;s name or extension requires <code>--override-builtin</code>, and discovery prints a line when one takes effect.</p><h2 id="cache-location" tabindex="-1">Cache location <a class="header-anchor" href="#cache-location" aria-label="Permalink to &quot;Cache location&quot;">​</a></h2><p><code>global_grammars_dir()</code>: <code>$CODEMARK_GRAMMARS_DIR</code> → <code>cache_dir/codemark/grammars</code>.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Path</th></tr></thead><tbody><tr><td>macOS</td><td><code>~/Library/Caches/codemark/grammars/</code></td></tr><tr><td>Linux</td><td><code>~/.cache/codemark/grammars/</code></td></tr><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\codemark\\cache\\grammars\\</code></td></tr></tbody></table><p>Layout: <code>&lt;cache&gt;/&lt;lang&gt;/grammar.wasm</code> + <code>&lt;cache&gt;/&lt;lang&gt;/manifest.json</code>.</p><h2 id="the-manifest" tabindex="-1">The manifest <a class="header-anchor" href="#the-manifest" aria-label="Permalink to &quot;The manifest&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;luau&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;profile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;landmark_kinds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function_declaration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function_definition&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;node_labels&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;function_declaration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;containers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function_declaration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Every field is explained in detail — including who reads it and how each one fails — in <a href="https://github.com/DanielCardonaRojas/codemark/blob/main/dev-docs/guides/manifest-anatomy.md" target="_blank" rel="noreferrer">the manifest anatomy guide</a>.</p><p>The <code>profile</code> is optional (omitting it writes <code>{}</code>). Every field is <code>#[serde(default)]</code>, so partial profiles work — but a <code>landmark_kinds</code> with the right node types is what makes bookmarks anchor correctly for a new language. See <a href="./query-generation">Query Generation</a> for what landmarks do.</p><h2 id="installing-a-grammar" tabindex="-1">Installing a grammar <a class="header-anchor" href="#installing-a-grammar" aria-label="Permalink to &quot;Installing a grammar&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> languages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/grammar.wasm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lua</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lua,luau</span></span></code></pre></div><h3 id="from-the-registry-in-one-command" tabindex="-1">From the registry, in one command <a class="header-anchor" href="#from-the-registry-in-one-command" aria-label="Permalink to &quot;From the registry, in one command&quot;">​</a></h3><p>If the registry has your language, this is the whole process — no Docker, no emscripten, no hunting for the right release asset:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> languages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> languages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruby</span></span></code></pre></div><p>It downloads the grammar the registry pins, <strong>verifies it against a SHA-256 recorded in the index</strong>, and installs it with the curated profile. A checksum mismatch aborts before anything is written. The download URL is also required to share a host with the entry&#39;s <code>grammar_repo</code>, so an entry can&#39;t point at an unrelated binary.</p><p>Entries without a prebuilt <code>.wasm</code> fall back to supplying one yourself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> languages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tree-sitter-lua.wasm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lua</span></span></code></pre></div><p><code>--name</code> and <code>--extensions</code> become optional (the registry supplies them) and still win as overrides. The registry ships <strong>profiles, not binaries</strong>: you build the <code>.wasm</code> yourself, which is why there&#39;s no ABI or licensing surprise in what you download.</p><p>The <strong>index</strong> is cached under <code>&lt;cache&gt;/.registry/</code> (keyed by registry URL), so <code>registry list</code> keeps working offline once you&#39;ve fetched it; <code>--refresh</code> forces a re-fetch. Profile manifests are <em>not</em> cached — installing a language needs the registry reachable. Point <code>registry_url</code> at a fork, an internal mirror, or a <code>file://</code> path for air-gapped use:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.config/codemark/config.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grammars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">registry_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:///srv/codemark-grammars&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index_ttl_secs = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86400</span></span></code></pre></div><p><code>CODEMARK_GRAMMAR_REGISTRY</code> overrides it for a single run.</p><p>A registry profile gets no special trust: it is schema-checked, linted against the grammar, and run through the same name/extension validation as a hand-typed <code>--name</code> — so claiming <code>.rs</code> or shadowing a built-in requires <code>--override-builtin</code> from a registry entry exactly as it does from the command line. Fetches require HTTPS (except localhost) and are size-capped.</p><p><code>--name</code> and <code>--extensions</code> let you override what the manifest declares. The install is <strong>hardened</strong> — it never lets an unloadable grammar replace a working one:</p>`,28)),(e(),l(c,null,{default:i(()=>[h(t,{id:"mermaid-109",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22languages%20add%20file.wasm%5Cn--name%20--exts%22%5D%20--%3E%20B%5B%22read%20bytes%20%E2%89%A4%2032%20MiB%5Cn(rejects%20FIFOs%2Fdevices)%22%5D%0A%20%20B%20--%3E%20C%5B%22validate%20name%20%2B%20extensions%5Cnbuiltin%20collision%20needs%20--override-builtin%22%5D%0A%20%20C%20--%3E%20D%5B%22stage%20into%20.staging-name-pid%22%5D%0A%20%20D%20--%3E%20E%5B%22wasm%20build%3A%20load%20staged%20grammar%5Cnto%20confirm%20it's%20valid%22%5D%0A%20%20E%20--%3E%20F%5B%22acquire%20per-name%20lock%20.lock-name%22%5D%0A%20%20F%20--%3E%20G%7B%22target%20exists%3F%22%7D%0A%20%20G%20--%20no%20--%3E%20H%5B%22atomic%20rename%20staging%20%E2%86%92%20name%22%5D%0A%20%20G%20--%20yes%20--%3E%20I%5B%22rename%20name%20%E2%86%92%20.bak-name%22%5D%0A%20%20I%20--%3E%20J%5B%22rename%20staging%20%E2%86%92%20name%22%5D%0A%20%20J%20--%20fail%20--%3E%20K%5B%22restore%20.bak-name%20%E2%86%92%20name%22%5D%0A%20%20J%20--%20ok%20--%3E%20L%5B%22remove%20.bak-name%22%5D%0A%20%20H%20--%3E%20Done%5B%22install%20complete%22%5D%0A%20%20L%20--%3E%20Done%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s(`<p>Key safety properties:</p><ul><li><strong>Stage-then-swap.</strong> The grammar is written to a staging dir, validated, then swapped in atomically.</li><li><strong>Pre-swap validation.</strong> On WASM builds, the staged grammar is loaded <em>before</em> the swap — an unloadable file can never replace a working one.</li><li><strong>Anti-symlink writes.</strong> Files are written with <code>O_NOFOLLOW</code> (Unix) / reparse-point handling (Windows) to block symlink-redirect attacks.</li><li><strong>32 MiB cap.</strong> Grammar files larger than 32 MiB are rejected.</li><li><strong>Crash recovery.</strong> If an install is interrupted, the next process start restores any <code>.bak-&lt;name&gt;</code> whose target is missing — so a killed installer can&#39;t leave you with a missing grammar.</li></ul><h2 id="discovery-at-startup" tabindex="-1">Discovery at startup <a class="header-anchor" href="#discovery-at-startup" aria-label="Permalink to &quot;Discovery at startup&quot;">​</a></h2><p>On first access, the global registry scans the cache dir, sorts entries by path (deterministic conflict resolution — first by sorted path wins), skips dot-prefixed staging/backup/lock files, parses each <code>manifest.json</code>, and registers by lowercased name + extension. The TUI re-scans on events so newly installed grammars appear without a restart.</p><h2 id="managing-grammars" tabindex="-1">Managing grammars <a class="header-anchor" href="#managing-grammars" aria-label="Permalink to &quot;Managing grammars&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>codemark languages add &lt;file&gt;</code></td><td>Install a grammar (see above).</td></tr><tr><td><code>codemark languages install &lt;lang&gt;</code></td><td>Download + verify + install from the registry.</td></tr><tr><td><code>codemark languages add &lt;file&gt; --from-registry &lt;lang&gt;</code></td><td>Install your own <code>.wasm</code> with a curated profile.</td></tr><tr><td><code>codemark languages registry list</code></td><td>List languages with a curated profile available.</td></tr><tr><td><code>codemark languages list</code></td><td>List all supported languages (built-ins + dynamic).</td></tr><tr><td><code>codemark languages validate</code></td><td>Verify each grammar loads <strong>and lint its profile</strong> (see below).</td></tr></tbody></table><h2 id="validating-a-profile" tabindex="-1">Validating a profile <a class="header-anchor" href="#validating-a-profile" aria-label="Permalink to &quot;Validating a profile&quot;">​</a></h2><p>A profile is a set of node kinds and field names, and they&#39;re grammar-specific — Lua has <code>function_call</code>, not <code>call_expression</code>. A kind the grammar doesn&#39;t define parses fine as a string and then never matches anything, so <code>codemark languages validate</code> checks every one against the loaded grammar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ codemark languages validate</span></span>
<span class="line"><span>Found issues with installed grammars:</span></span>
<span class="line"><span>  - .../grammars/ruby: error: profile.landmark_kinds[1]: node kind &#39;function_item&#39;</span></span>
<span class="line"><span>    is not defined by this grammar, so it can never match (did you mean &#39;method&#39;?)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Warnings (these grammars still work):</span></span>
<span class="line"><span>  - .../grammars/ruby: warning: profile.containers: no containers, so this</span></span>
<span class="line"><span>    language produces no breadcrumbs</span></span></code></pre></div><p><strong>Errors</strong> mean that part of the profile is dead — it can never match. They also block an install, so a bad profile can&#39;t replace a working grammar. <strong>Warnings</strong> are advisory and don&#39;t affect <code>valid</code>. Note that <code>containers</code> has no fallback: an empty one means breadcrumbs are silently blank, which is why it&#39;s called out.</p><p>The two error kinds cost you different things. An unknown <strong>node kind</strong> is dead weight — nothing can ever match it, and a wrong <code>containers[].0</code> is the usual cause of blank breadcrumbs. An unknown <strong>container field</strong> blocks the install but doesn&#39;t affect matching, since breadcrumb extraction reads only the kind.</p><p>One limit of the lint: tree-sitter exposes field names globally rather than per node kind, so a container field that is real <em>somewhere</em> in the grammar passes validation even if its paired kind doesn&#39;t carry it. Today that is cosmetic — breadcrumbs match on the node kind alone and never read the field — but it means a clean <code>validate</code> isn&#39;t proof the pair is right. <code>languages profile init</code> derives the field from an actual parse.</p><div class="tip custom-block"><p class="custom-block-title">Non-WASM builds</p><p>If you compiled the CLI yourself with <code>--no-default-features</code> (dropping the <code>wasm</code> feature), dynamic grammars can be <em>installed</em> but won&#39;t <em>run</em> until you rebuild with <code>--features wasm</code>. The install command warns you when runtime support is disabled.</p></div>`,13))])}const F=n(p,[["render",g]]);export{E as __pageData,F as default};
